kubectlcurl <pre><code>kubectl patch psmdb my-cluster-name -n $NAMESPACE --type=json -p='[
  {"op": "replace", "path": "/spec/image", "value": "percona/percona-server-mongodb:8.0.26-11"}
]'
</code></pre> <pre><code>curl -k -XPATCH \
  "https://$API_SERVER/apis/psmdb.percona.com/v1/namespaces/$NAMESPACE/perconaservermongodbs/my-cluster-name" \
  -H "Authorization: Bearer $KUBE_TOKEN" \
  -H "Content-Type: application/json-patch+json" \
  -H "Accept: application/json" \
  -d '[
    {"op": "replace", "path": "/spec/image", "value": "percona/percona-server-mongodb:8.0.26-11"}
  ]'
</code></pre>
